nums = [int(x) for x in input().split()]
min_val = nums[0]
max_val = nums[0]
for x in nums[1:]:
    if x < min_val:
        min_val = x
    if x > max_val:
        max_val = x
print(f"Min: {min_val}, Max: {max_val}")

nums = [int(x) for x in input().split()]
pos = neg = zero = 0
for x in nums:
    if x > 0:
        pos += 1
    elif x < 0:
        neg += 1
    else:
        zero += 1
print(f"Pos: {pos}, Neg: {neg}, Zero: {zero}")

nums = [int(x) for x in input().split()]
largest = None
second = None
for x in nums:
    if largest is None or x > largest:
        second = largest
        largest = x
    elif x != largest and (second is None or x > second):
        second = x
print(second if second is not None else "None")

nums = [int(v) for v in input().split()]
x = int(input())
write = 0
for num in nums:
    if num != x:
        nums[write] = num
        write += 1
if write == 0:
    print("Empty")
else:
    print(" ".join(str(nums[i]) for i in range(write)))

nums = [int(x) for x in input().split()]
counts = {}
for x in nums:
    counts[x] = counts.get(x, 0) + 1
for val, cnt in counts.items():
    print(f"{val}: {cnt}")

nums = [int(x) for x in input().split()]
target = int(input())
seen = {}
result = "None"
for j, x in enumerate(nums):
    need = target - x
    if need in seen:
        result = f"{seen[need]} {j}"
        break
    if x not in seen:
        seen[x] = j
print(result)

nums = [int(x) for x in input().split()]
evens = []
odds = []
for x in nums:
    if x % 2 == 0:
        evens.append(str(x))
    else:
        odds.append(str(x))
print(" ".join(evens + odds))

nums = [int(x) for x in input().split()]
candidate = None
count = 0
for x in nums:
    if count == 0:
        candidate = x
    count += 1 if x == candidate else -1

actual = 0
for x in nums:
    if x == candidate:
        actual += 1

print(candidate if actual > len(nums) // 2 else "None")

n = int(input())
intervals = []
for _ in range(n):
    s, e = [int(x) for x in input().split()]
    intervals.append([s, e])
intervals.sort()
merged = [intervals[0]]
for s, e in intervals[1:]:
    if s <= merged[-1][1]:
        if e > merged[-1][1]:
            merged[-1][1] = e
    else:
        merged.append([s, e])
for s, e in merged:
    print(f"{s} {e}")
